async def act(page):
    # Plan:
    # 1. Use a relative navigation to the New Shopping Cart Price Rule page.
    # 2. Fill the rule general details (Rule Name, Description, Status, Websites, Customer Groups, Coupon).
    # 3. Open the Actions tab and set the discount to 45% (Percent of product price discount).
    # 4. Save the rule (final action that triggers navigation/submit).
    # Note: Using accessibility-focused selectors (get_by_role / get_by_label) only.

    # 1) Navigate directly to the New Shopping Cart Price Rule page (relative URL)
    await page.goto('/index.php/admin/promo_quote/new/')
    await page.wait_for_load_state('networkidle')

    # 2) Fill General information
    # Rule Name
    try:
        await page.get_by_role("textbox", name="Rule Name").fill('Pride Month - 45% Off')
    except Exception:
        # fallback using label-based API if role-based selection is different
        try:
            await page.get_by_label('Rule Name').fill('Pride Month - 45% Off')
        except Exception:
            pass

    # Description (textarea) - try label first
    try:
        await page.get_by_label('Description').fill('45% off everything for Pride Month for all customers.')
    except Exception:
        # try role-based textbox with name Description
        try:
            await page.get_by_role('textbox', name='Description').fill('45% off everything for Pride Month for all customers.')
        except Exception:
            pass

    # Status -> select Active
    try:
        await page.get_by_role('combobox', name='Status').select_option(label='Active')
    except Exception:
        try:
            # fallback via label selector
            await page.get_by_label('Status').select_option(label='Active')
        except Exception:
            pass

    # Websites: check all website checkboxes so rule applies to all websites
    try:
        websites_group = page.get_by_role('group', name='Websites')
        website_checkboxes = websites_group.get_by_role('checkbox')
        count = await website_checkboxes.count()
        for i in range(count):
            cb = website_checkboxes.nth(i)
            try:
                await cb.check()
            except Exception:
                # ignore if already checked or not interactable
                pass
    except Exception:
        # fallback: try to check any checkbox that looks like website selection
        try:
            all_checkboxes = page.get_by_role('checkbox')
            # Attempt to check any unchecked boxes (be conservative and check up to 10)
            total = await all_checkboxes.count()
            for i in range(min(total, 10)):
                cb = all_checkboxes.nth(i)
                try:
                    await cb.check()
                except Exception:
                    pass
        except Exception:
            pass

    # Customer Groups: select all customer group checkboxes
    try:
        cust_group = page.get_by_role('group', name='Customer Groups')
        cust_checkboxes = cust_group.get_by_role('checkbox')
        cg_count = await cust_checkboxes.count()
        for i in range(cg_count):
            cb = cust_checkboxes.nth(i)
            try:
                await cb.check()
            except Exception:
                pass
    except Exception:
        # fallback: try to check more checkboxes if available
        try:
            all_checkboxes = page.get_by_role('checkbox')
            total = await all_checkboxes.count()
            for i in range(min(total, 20)):
                try:
                    await all_checkboxes.nth(i).check()
                except Exception:
                    pass
        except Exception:
            pass

    # Coupon -> No Coupon
    try:
        await page.get_by_role('combobox', name='Coupon').select_option(label='No Coupon')
    except Exception:
        try:
            await page.get_by_label('Coupon').select_option(label='No Coupon')
        except Exception:
            pass

    # 3) Actions tab: set discount type and amount
    try:
        await page.get_by_role('tab', name='Actions').click()
    except Exception:
        # sometimes Actions is a link or button
        try:
            await page.get_by_role('link', name='Actions').click()
        except Exception:
            try:
                await page.get_by_role('button', name='Actions').click()
            except Exception:
                pass

    # Set Apply -> Percent of product price discount
    try:
        await page.get_by_role('combobox', name='Apply').select_option(label='Percent of product price discount')
    except Exception:
        try:
            await page.get_by_label('Apply').select_option(label='Percent of product price discount')
        except Exception:
            # try common value fallback
            try:
                await page.get_by_role('combobox', name='Apply').select_option(value='by_percent')
            except Exception:
                pass

    # Discount Amount -> 45
    try:
        await page.get_by_role('textbox', name='Discount Amount').fill('45')
    except Exception:
        try:
            await page.get_by_label('Discount Amount').fill('45')
        except Exception:
            pass

    # 4) Save the rule - final action (this will submit the form)
    save_clicked = False
    for save_name in ['Save Rule', 'Save', 'Save and Continue Edit']:
        try:
            btn = page.get_by_role('button', name=save_name)
            if await btn.count() > 0:
                await btn.first.click()
                save_clicked = True
                break
        except Exception:
            continue

    if not save_clicked:
        # try other common save affordances
        try:
            await page.get_by_role('button', name='Save').click()
            save_clicked = True
        except Exception:
            try:
                await page.get_by_role('button', name='Save Rule').click()
                save_clicked = True
            except Exception:
                pass

    if save_clicked:
        # wait for navigation or network idle after save
        try:
            await page.wait_for_load_state('networkidle')
        except Exception:
            await page.wait_for_load_state('load')

